import { paths, routesByAction, type RouteInfo, type StrapiEngine } from 'devkit-for-strapi-core';
import * as vscode from 'vscode';
import { DOCUMENT_SELECTOR, docPath } from '../selector';

/**
 * "GET /api/articles/:id · PUT /api/articles/:id" above each controller action:
 * the routes that call it — which the controller file itself never says (they are
 * declared in route files, generated by `createCoreRouter`, or by plugins).
 */

const MAX_IN_TITLE = 3;

function label(r: RouteInfo): string {
  return `${r.method.toUpperCase()} ${r.fullPath ?? r.path}`;
}

export interface RoutesCodeLenses {
  refresh(): void;
}

export function registerRoutesCodeLens(context: vscode.ExtensionContext, engine: StrapiEngine): RoutesCodeLenses {
  const onDidChange = new vscode.EventEmitter<void>();
  context.subscriptions.push(
    onDidChange,
    vscode.workspace.onDidChangeConfiguration((e) => {
      if (e.affectsConfiguration('strapiDevkit.routesCodeLens')) onDidChange.fire();
    }),
    vscode.languages.registerCodeLensProvider(DOCUMENT_SELECTOR, {
      onDidChangeCodeLenses: onDidChange.event,
      async provideCodeLenses(document) {
        if (!vscode.workspace.getConfiguration('strapiDevkit.routesCodeLens').get<boolean>('enable', true)) return [];
        const file = paths.normalize(docPath(document));
        const project = engine.projectForFile(file);
        if (!project) return [];
        const controllers = [...project.index.controllers.values()].filter((c) => !c.installed && paths.normalize(c.filePath) === file);
        if (!controllers.length) return [];
        try {
          const routes = (await engine.getRoutes({ admin: true, root: project.root }))[0]?.routes ?? [];
          const byAction = routesByAction(routes);
          const lenses: vscode.CodeLens[] = [];
          for (const c of controllers) {
            for (const a of c.actions ?? []) {
              if (a.filePath && paths.normalize(a.filePath) !== file) continue;
              const hits = byAction.get(`${c.ref}.${a.name}`);
              if (!hits?.length) continue;
              const pos = document.positionAt(a.offset);
              const shown = hits.slice(0, MAX_IN_TITLE).map(label).join(' · ');
              const title = hits.length > MAX_IN_TITLE ? `${shown} · +${hits.length - MAX_IN_TITLE}` : shown;
              lenses.push(
                new vscode.CodeLens(new vscode.Range(pos, pos), {
                  title: `$(globe) ${title}`,
                  tooltip: `Routes handled by ${c.ref}.${a.name}`,
                  command: 'strapiDevkit.routes.pick',
                  arguments: [project.root, hits],
                }),
              );
            }
          }
          return lenses;
        } catch {
          return [];
        }
      },
    }),
    vscode.commands.registerCommand('strapiDevkit.routes.pick', async (root: string, hits: RouteInfo[]) => {
      const pick =
        hits.length === 1
          ? hits[0]
          : (
              await vscode.window.showQuickPick(
                hits.map((r) => ({ label: label(r), description: r.handler, detail: r.filePath ? vscode.workspace.asRelativePath(r.filePath) : undefined, r })),
                { title: 'Routes handled by this action' },
              )
            )?.r;
      if (!pick) return;
      // Show it in the Routes view (its pipeline) and open its declaration.
      await vscode.commands.executeCommand('strapiDevkit.routes.reveal', root, pick, false);
      if (pick.filePath) await vscode.commands.executeCommand('strapiDevkit.routes.open', pick.filePath, pick.offset ?? 0);
    }),
  );
  return { refresh: () => onDidChange.fire() };
}
